      "id": "SRE-004",
      "name": "Containerization & Orchestration",
      "category": "SRE",
      "description": "Working with Docker containers and managing deployments using Kubernetes.",
      "duration": "4 hours",
      "targetRoles": [
        "SRE"
      ],
      "targetSection": null,
